@keyframes v-tick {
  0% {
    transform: scale(0.8);
    border-radius: 54% 46% 50% 50%/46% 50% 50% 54%;
  }
  55% {
    transform: scale(1.14, 0.94);
    border-radius: 50% 50% 46% 54%/54% 50% 46% 50%;
  }
  80% {
    transform: scale(0.98, 1.04);
  }
  100% {
    transform: scale(1);
    border-radius: 46% 54% 50% 50%/50% 46% 54% 50%;
  }
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="radio-group"],
  [data-slot^="radio-group-"],
  [data-slot="radio-group"]::before,
  [data-slot="radio-group"]::after,
  [data-slot^="radio-group-"]::before,
  [data-slot^="radio-group-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

[data-slot="radio-group-item"]:focus-visible {
  outline: none;
}
[data-slot="radio-group-item"]:focus-visible
  [data-slot="radio-group-indicator"],
[data-slot="radio-group-item"][data-pictographic]:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}
[data-slot="radio-group-item"]:active [data-slot="radio-group-indicator"] {
  transform: scale(0.92);
}
[data-slot="radio-group-dot"] {
  display: none;
}

/* Radix uses a button for the source label; retain the label's inherited alignment. */
.v-radio:where([data-slot="radio-group-item"]) { text-align: start; }

